/* ═══════════════════════════════════════════════════════════════
 * MMDS — سامانه هوشمند آنالیز ادوات نیروگاهی (نسخه تک‌فایل)
 * کل سیستم = همین یک فایل. هیچ فایل جانبی لازم نیست.
 * نصب: کپی در public_html → تمام. بدون دیتابیس، بدون تنظیمات.
 * ═══════════════════════════════════════════════════════════════ */
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: no-referrer');

$m = isset($_GET['mmds']) ? $_GET['mmds'] : '';
if ($m === 'manifest') {
  header('Content-Type: application/manifest+json; charset=utf-8');
  header('Cache-Control: public, max-age=86400');
  echo <<<'MMDS_MANIFEST'
{"name": "MMDS — آنالیز ادوات نیروگاهی", "short_name": "MMDS", "description": "تحلیل آفلاین ویبره/جریان/حرارتی/رله موتورها و ادوات نیروگاهی", "lang": "fa", "dir": "rtl", "start_url": "./", "scope": "./", "display": "standalone", "orientation": "portrait", "background_color": "#0d1420", "theme_color": "#101a2e", "icons": [{"src": "data:image/png;base64,", "sizes": "192x192", "type": "image/png", "purpose": "any"}, {"src": "data:image/png;base64,", "sizes": "512x512", "type": "image/png", "purpose": "any"}]}
MMDS_MANIFEST;
  exit;
}
if ($m === 'sw') {
  header('Content-Type: text/javascript; charset=utf-8');
  header('Cache-Control: no-cache');
  header('Service-Worker-Allowed: ./');
  echo <<<'MMDS_SW'
// MMDS single-file SW — آفلاین کامل (همه‌چیز از همین index.php سرو می‌شود)
const CACHE = "mmds-single-v1";
self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.add("./")).then(() => self.skipWaiting()));
});
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("fetch", e => {
  e.respondWith(
    caches.match(e.request).then(hit => hit || fetch(e.request).then(resp => {
      if (e.request.method === "GET" && resp.status === 200) {
        const cl = resp.clone(); caches.open(CACHE).then(c => c.put(e.request, cl));
      }
      return resp;
    }).catch(() => caches.match("./")))
  );
});

MMDS_SW;
  exit;
}
header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-cache');
