<script>/* MMDS آنالایزر درون‌مرورگر — پورت JavaScript از هسته تحلیل پوش پایتون
 * خالصِ تابعی: هم در مرورگر و هم در Node (برای تست) کار می‌کند.
 * خروجی اصلی: MMDS_ANALYZE.analyze(x, fs, rpm, bearing) */
(function (G) {
  "use strict";

  // ─────────────── بلبرینگ‌ها (n تعداد غلطک، d قطر غلطک، D گام قطر mm) ───────────────
  const BEARINGS = {
    "6204": { n: 8, d: 7.94,  D: 34.55 },
    "6205": { n: 9, d: 7.94,  D: 39.04 },
    "6206": { n: 9, d: 9.525, D: 46.0  },
    "6207": { n: 9, d: 11.112,D: 53.98 },
    "6305": { n: 8, d: 11.91, D: 46.45 },
  };

  function bearingFreqs(fr, brg) {
    const { n, d, D } = brg;
    const FTF  = 0.5 * (1 - d / D) * fr;
    const BPFO = n * FTF;
    const BPFI = 0.5 * n * (1 + d / D) * fr;
    const BSF  = 0.5 * (D / d) * (1 - (d / D) ** 2) * fr;
    return { FTF, BPFO, BPFI, BSF };
  }

  // ─────────────── FFT رادیکس-۲ (iterative) ───────────────
  function fft(re, im) {
    const n = re.length;
    for (let i = 1, j = 0; i < n; i++) {
      let bit = n >> 1;
      for (; j & bit; bit >>= 1) j ^= bit;
      j ^= bit;
      if (i < j) { [re[i], re[j]] = [re[j], re[i]]; [im[i], im[j]] = [im[j], im[i]]; }
    }
    for (let len = 2; len <= n; len <<= 1) {
      const ang = -2 * Math.PI / len, wr = Math.cos(ang), wi = Math.sin(ang);
      const half = len >> 1;
      for (let i = 0; i < n; i += len) {
        let cwr = 1, cwi = 0;
        for (let k = 0; k < half; k++) {
          const ur = re[i + k], ui = im[i + k];
          const vr = re[i + k + half] * cwr - im[i + k + half] * cwi;
          const vi = re[i + k + half] * cwi + im[i + k + half] * cwr;
          re[i + k] = ur + vr;        im[i + k] = ui + vi;
          re[i + k + half] = ur - vr; im[i + k + half] = ui - vi;
          const nr = cwr * wr - cwi * wi; cwi = cwr * wi + cwi * wr; cwr = nr;
        }
      }
    }
  }

  // ─────────────── فیلتر بیکواد (RBJ Butterworth) ───────────────
  function biquadCoeffs(type, fc, fs, Q) {
    const w0 = 2 * Math.PI * fc / fs, cw = Math.cos(w0), sw = Math.sin(w0);
    const alpha = sw / (2 * Q);
    let b0, b1, b2;
    if (type === "lpf") {
      b0 = (1 - cw) / 2; b1 = 1 - cw; b2 = (1 - cw) / 2;
    } else {
      b0 = (1 + cw) / 2; b1 = -(1 + cw); b2 = (1 + cw) / 2;
    }
    const a0 = 1 + alpha, a1 = -2 * cw, a2 = 1 - alpha;
    return [b0 / a0, b1 / a0, b2 / a0, a1 / a0, a2 / a0];
  }
  function biquadRun(x, c) {
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    const y = new Float64Array(x.length);
    for (let i = 0; i < x.length; i++) {
      const x0 = x[i];
      const y0 = c[0] * x0 + c[1] * x1 + c[2] * x2 - c[3] * y1 - c[4] * y2;
      x2 = x1; x1 = x0; y2 = y1; y1 = y0;
      y[i] = y0;
    }
    return y;
  }
  // باترورث مرتبه ۴ باندپس: HPF(۲biquad) در [2000Hz] + LPF(۲biquad) در [0.46fs]
  function bandpass4(x, fs, fLo, fHi) {
    let y = x;
    for (const Q of [0.5412, 1.3065]) y = biquadRun(y, biquadCoeffs("hpf", fLo, fs, Q));
    for (const Q of [0.5412, 1.3065]) y = biquadRun(y, biquadCoeffs("lpf", fHi, fs, Q));
    return y;
  }

  // ─────────────── آمار ───────────────
  function mean(a) { let s = 0; for (const v of a) s += v; return s / a.length; }
  function kurt(a) {
    const m = mean(a); let v = 0, k = 0;
    for (const x of a) { const d = x - m; v += d * d; k += d ** 4; }
    v /= a.length; return (k / a.length) / Math.max(v * v, 1e-18);
  }

  // ─────────────── پارسر WAV خالص (PCM 8/16/24/32-int و ۳۲-float) ───────────────
  function parseWav(buf) {
    const dv = new DataView(buf);
    if (dv.getUint32(0, false) !== 0x52494646 || dv.getUint32(8, false) !== 0x57415645)
      throw new Error("فایل WAV نیست");
    let off = 12, fmt = null, dataOff = -1, dataLen = 0;
    while (off + 8 <= dv.byteLength) {
      const id = dv.getUint32(off, false), sz = dv.getUint32(off + 4, true);
      if (id === 0x666d7420) {
        fmt = { audioFormat: dv.getUint16(off + 8, true), channels: dv.getUint16(off + 10, true),
                sampleRate: dv.getUint32(off + 12, true), bits: dv.getUint16(off + 22, true),
                blockAlign: dv.getUint16(off + 20, true) };
      } else if (id === 0x64617461) { dataOff = off + 8; dataLen = sz; }
      off += 8 + sz + (sz & 1);
    }
    if (!fmt || dataOff < 0) throw new Error("ساختار WAV ناقص است");
    const nFrames = Math.floor(dataLen / fmt.blockAlign);
    const out = new Float64Array(nFrames);
    for (let i = 0; i < nFrames; i++) {
      let acc = 0;
      for (let ch = 0; ch < fmt.channels; ch++) {
        const p = dataOff + i * fmt.blockAlign + ch * (fmt.bits >> 3);
        let v = 0;
        if (fmt.audioFormat === 3 && fmt.bits === 32) v = dv.getFloat32(p, true);
        else if (fmt.bits === 16) v = dv.getInt16(p, true) / 32768;
        else if (fmt.bits === 24) {
          v = (dv.getUint8(p) | (dv.getUint8(p + 1) << 8) | (dv.getUint8(p + 2) << 16));
          if (v & 0x800000) v -= 0x1000000; v /= 8388608;
        }
        else if (fmt.bits === 32) v = dv.getInt32(p, true) / 2147483648;
        else v = (dv.getUint8(p) - 128) / 128;
        acc += v;
      }
      out[i] = acc / fmt.channels;
    }
    return { samples: out, sampleRate: fmt.sampleRate, channels: fmt.channels };
  }

  // ─────────────── تحلیل اصلی ───────────────
  function analyze(xIn, fs, rpm, brg, opts) {
    opts = opts || {};
    const kind = opts.kind || "vib";
    let x = xIn.length > 524288 ? xIn.slice(0, 524288) : Float64Array.from(xIn);
    const fr = rpm / 60;
    const frqs = bearingFreqs(fr, brg);
    const k = kurt(x);
    const rms = Math.sqrt(mean(Array.from(x, v => v * v)));
    const m0 = mean(x);
    let crest = 0;
    for (const v of x) crest = Math.max(crest, Math.abs(v - m0));
    crest /= Math.max(rms, 1e-12);

    // باندپس + پوش (Hilbert مبتنی بر FFT)
    const fLo = (opts.bandLo != null) ? opts.bandLo
              : (kind === "ac" ? Math.min(3500, fs * 0.25) : Math.min(2000, fs * 0.2));
    const fHi = fs * 0.46;
    const xf = bandpass4(x, fs, fLo, fHi);
    let N = 1; while (N < xf.length) N <<= 1;
    const re = new Float64Array(N), im = new Float64Array(N);
    for (let i = 0; i < xf.length; i++) re[i] = xf[i];
    fft(re, im);
    // سیگنال تحلیلی: فرکانس‌های مثبت ×۲
    for (let i = 1; i < N / 2; i++) { re[i] *= 2; im[i] *= 2; }
    for (let i = N / 2 + 1; i < N; i++) { re[i] = 0; im[i] = 0; }
    // IFFT = مزدوج FFT مزدوج / N
    for (let i = 0; i < N; i++) im[i] = -im[i];
    fft(re, im);
    const env = new Float64Array(xf.length);
    for (let i = 0; i < xf.length; i++) env[i] = Math.hypot(re[i], im[i]) / N;
    const em = mean(env);
    for (let i = 0; i < env.length; i++) env[i] -= em;

    // طیف پوش
    let M = 1; while (M < env.length) M <<= 1;
    const w = new Float64Array(env.length);
    let wsum = 0;
    for (let i = 0; i < env.length; i++) {
      w[i] = 0.5 * (1 - Math.cos(2 * Math.PI * i / (env.length - 1)));
      wsum += w[i];
    }
    const re2 = new Float64Array(M), im2 = new Float64Array(M);
    for (let i = 0; i < env.length; i++) re2[i] = env[i] * w[i];
    fft(re2, im2);
    const nh = M / 2;
    const Ae = new Float64Array(nh), fe = new Float64Array(nh);
    for (let i = 0; i < nh; i++) { Ae[i] = 2 * Math.hypot(re2[i], im2[i]) / wsum; fe[i] = i * fs / M; }

    // سهم توان فرکانس‌های عیب (همان منطق datasets_adapter)
    const P = new Float64Array(nh);
    for (let i = 0; i < nh; i++) P[i] = Ae[i] * Ae[i];
    let tot = 1e-18;
    for (let i = 0; i < nh; i++) if (fe[i] > 5 && fe[i] < 500) tot += P[i];
    function frac(f0, nHarm) {
      let s = 0;
      for (let h = 1; h <= nHarm; h++)
        for (let i = 0; i < nh; i++)
          if (fe[i] >= h * f0 - 1.5 && fe[i] <= h * f0 + 1.5) s += P[i];
      return s / tot;
    }
    const res = { bpfo: frac(frqs.BPFO, 3), bpfi: frac(frqs.BPFI, 3), bsf: frac(frqs.BSF, 2) };
    const entries = [["BPFO", res.bpfo], ["BPFI", res.bpfi], ["BSF", res.bsf]];
    const best = entries.reduce((a, b) => b[1] > a[1] ? b : a);

    // حکم (همان قواعد آستانه)
    let code, faName, level;
    if (best[1] < 0.06) { code = "H00"; faName = "سالم"; level = "ok"; }
    else {
      const m = { BPFO: ["B01", "نقص رینگ بیرونی"], BPFI: ["B02", "نقص رینگ داخلی"], BSF: ["B03", "نقص غلطک/قفسه"] };
      [code, faName] = m[best[0]];
      level = best[1] > 0.12 ? "alarm" : "watch";
    }

    // ── متریک‌های صوت (کانال ac): مرکز جرم طیفی + انرژی باندها ──
    let ac = null;
    if (kind === "ac") {
      let Mx = 1; while (Mx < x.length) Mx <<= 1;
      const w0 = new Float64Array(x.length); let wsum0 = 0;
      for (let i = 0; i < x.length; i++) {
        w0[i] = 0.5 * (1 - Math.cos(2 * Math.PI * i / (x.length - 1))); wsum0 += w0[i];
      }
      const re3 = new Float64Array(Mx), im3 = new Float64Array(Mx);
      const xv = new Float64Array(x.length);
      const xm = mean(x);
      for (let i = 0; i < x.length; i++) re3[i] = (x[i] - xm) * w0[i];
      fft(re3, im3);
      const nq = Mx / 2; let totA = 1e-18, csum = 0;
      const b = [0, 0, 0, 0];
      for (let i = 1; i < nq; i++) {
        const f = i * fs / Mx; if (f < 20) continue;
        const p = (re3[i] * re3[i] + im3[i] * im3[i]);
        totA += p; csum += f * p;
        if (f < 200) b[0] += p; else if (f < 1000) b[1] += p;
        else if (f < 4000) b[2] += p; else b[3] += p;
      }
      ac = { centroid: csum / totA, b1: b[0] / totA, b2: b[1] / totA, b3: b[2] / totA, b4: b[3] / totA };
    }
    return { code, faName, level, best: best[0], bestVal: best[1], kind,
             kurt: k, rms, crest, frqs, res, fe, Ae, fLo, fHi, n: x.length, ac };
  }

  // ─────────────── پارس CSV ───────────────
  function parseCsv(text) {
    const lines = text.split(/\r?\n/).filter(l => l.trim() && !/^#/.test(l.trim()));
    let start = 0, col = 0;
    const header = lines[0].split(/[,;\t]/).map(s => s.trim().toLowerCase());
    const vi = header.findIndex(h => h === "vib");
    if (vi >= 0) { col = vi; start = 1; }
    else if (header.some(h => isNaN(parseFloat(h)))) { start = 1; col = 0; }
    const out = [];
    for (let i = start; i < lines.length; i++) {
      const v = parseFloat(lines[i].split(/[,;\t]/)[col]);
      if (!isNaN(v)) out.push(v);
    }
    return out;
  }

  // ═══════════════ MCSA — آنالیز جریان (پورت از mcsa_quick.py) ═══════════════
  const TH_BRB = { watch: -54, warning: -42, alarm: -33 };

  function goertzel(x, fs, f0) {
    let sr = 0, si = 0;
    const w = 2 * Math.PI * f0 / fs;
    for (let n = 0; n < x.length; n++) {
      sr += x[n] * Math.cos(w * n); si -= x[n] * Math.sin(w * n);
    }
    return 2 * Math.hypot(sr, si) / x.length;
  }

  function refineF1(x, fs, linef) {
    let f0 = linef;
    for (const st of [0.8, 0.08]) {
      let best = 0, bf = f0;
      for (let g = f0 - st; g <= f0 + st + 1e-9; g += st / 10) {
        const a = goertzel(x, fs, g); if (a > best) { best = a; bf = g; }
      }
      f0 = Math.min(linef + 4, Math.max(linef - 4, bf));
    }
    return f0;
  }

  function bandMax(x, fs, fc, half, n = 25) {
    let m = 0;
    for (let i = 0; i < n; i++)
      m = Math.max(m, goertzel(x, fs, fc - half + 2 * half * i / (n - 1)));
    return m;
  }

  function analyzeCurrent(xIn, fs, linef, slip, fr) {
    let x = xIn.length > 524288 ? xIn.slice(0, 524288) : Float64Array.from(xIn);
    const xc = new Float64Array(x.length);
    const xm = mean(x);
    for (let i = 0; i < x.length; i++) xc[i] = x[i] - xm;
    const f1m = refineF1(xc, fs, linef || 50);
    const a1 = goertzel(xc, fs, f1m);
    // حذف فازور مؤلفه اصلی
    let cr = 0, ci = 0;
    const w1 = 2 * Math.PI * f1m / fs;
    for (let n = 0; n < xc.length; n++) { cr += xc[n] * Math.cos(-w1 * n); ci += xc[n] * Math.sin(-w1 * n); }
    cr *= 2 / xc.length; ci *= 2 / xc.length;
    const res = new Float64Array(xc.length);
    for (let n = 0; n < xc.length; n++)
      res[n] = xc[n] - (cr * Math.cos(w1 * n) - ci * Math.sin(w1 * n));
    const fLb = f1m * (1 - 2 * slip), fUb = f1m * (1 + 2 * slip);
    const half = Math.max(0.35, 0.30 * f1m * slip);
    const aLb = bandMax(res, fs, fLb, half), aUb = bandMax(res, fs, fUb, half);
    const brbDb = 20 * Math.log10(Math.max((aLb + aUb) / (2 * a1 + 1e-12), 1e-9));
    // نویز مرجع
    const nz = [];
    for (let g = f1m - 8; g <= f1m + 8; g += 0.4) {
      if (Math.abs(g - f1m) < 1 || Math.abs(g - fLb) < 1.3 * half || Math.abs(g - fUb) < 1.3 * half) continue;
      nz.push(goertzel(res, fs, g));
    }
    nz.sort((a, b) => a - b);
    const noiseN = nz[Math.floor(nz.length / 2)] + 1e-15;
    const sbSnr = (aLb + aUb) / 2 / noiseN;
    // THD — باند ±0.2Hz دور هر هارمونیک
    let h2 = 0;
    for (let h = 2; h <= 10; h++) h2 += (bandMax(xc, fs, h * f1m, 0.2) / (a1 + 1e-12)) ** 2;
    const thd = 100 * Math.sqrt(h2);
    // فاصله هوایی (اختیاری)
    let eccDb = null;
    if (fr && fr > 3 && fr < f1m - 5) {
      const aEc = (goertzel(res, fs, f1m - fr) + goertzel(res, fs, f1m + fr)) / 2;
      eccDb = 20 * Math.log10(Math.max(aEc / (a1 + 1e-12), 1e-9));
    }
    const findings = [];
    if (brbDb > TH_BRB.watch)
      findings.push({ code: "R01", fa: "شکستگی/ترک میله روتور",
        level: brbDb > TH_BRB.alarm ? "alarm" : brbDb > TH_BRB.warning ? "warning" : "watch",
        detail: `سایدبند (1±2s)f₁ = ${brbDb.toFixed(1)} dB (SNR ${sbSnr.toFixed(0)}×)` });
    if (eccDb !== null && eccDb > -55)
      findings.push({ code: "R02", fa: "عدم تقارن فاصله هوایی", level: "watch",
        detail: `خطوط f₁±fᵣ = ${eccDb.toFixed(1)} dB` });
    if (thd > 8)
      findings.push({ code: "P01", fa: "اعوجاج هارمونیکی", level: "watch",
        detail: `THD=${thd.toFixed(1)}%` });
    const L = ["ok", "watch", "warning", "alarm"];
    const worst = findings.reduce((w, f) => L.indexOf(f.level) > L.indexOf(w) ? f.level : w, "ok");
    return { f1: f1m, a1, brbDb, sbSnr, thd, eccDb, findings, worst };
  }

  // ═══════════════ ویبره ماشین‌آلات دوار نیروگاهی — پورت از machine_vib.py ═══════════════
  const ISO_GROUPS = {
    1: { name: "بزرگ سفت (۳۰۰kW–۵۰MW)", ab: 2.3, bc: 4.5, cd: 7.1 },
    2: { name: "متوسط سفت (۱۵–۳۰۰kW)", ab: 1.4, bc: 2.8, cd: 4.5 },
    3: { name: "بزرگ انعطاف", ab: 3.5, bc: 7.1, cd: 11.0 },
    4: { name: "متوسط انعطاف", ab: 2.3, bc: 4.5, cd: 7.1 },
  };

  function _hp4(x, fs, fc) {
    let y = x;
    for (const Q of [0.5412, 1.3065]) y = biquadRun(y, biquadCoeffs("hpf", fc, fs, Q));
    return y;
  }

  // آنالیز ماشین دوار: ISO 20816-3 Zone + مرتبه‌سنجی، منطبق بر machine_vib.py
  // unit: 'g' | 'mm/s' | 'arb' · blades: 0=نامشخص · journal: یاتاقان صفحه‌ای؟
  function analyzeMachine(xIn, fs, rpm, blades, unit, group, journal, machine) {
    const x = xIn.length > 500000 ? xIn.slice(0, 500000) : Float64Array.from(xIn);
    const xm = mean(x);
    for (let i = 0; i < x.length; i++) x[i] -= xm;
    const fr0 = rpm / 60, fhi = Math.min(1000, 0.45 * fs);

    // باند ISO ۱۰–۱۰۰۰Hz (باترورث-۴ دوطرفه hp+lp)
    const xb = bandpass4(x, fs, 10, fhi);

    // سرعت: انتگرال ذوزنقه‌ای + HP8 حذف رانش (+9810 برای g)
    let vel;
    if (unit === "mm/s") vel = Float64Array.from(xb);
    else {
      vel = new Float64Array(xb.length);
      for (let i = 1; i < xb.length; i++)
        vel[i] = vel[i - 1] + (xb[i] + xb[i - 1]) * 0.5 / fs;
      vel = _hp4(vel, fs, 8);
      if (unit === "g") for (let i = 0; i < vel.length; i++) vel[i] *= 9810;
    }
    let sv = 0; for (const v of vel) sv += v;
    const mv = sv / vel.length; let vv2 = 0;
    for (const v of vel) vv2 += (v - mv) ** 2;
    const vvv = Math.sqrt(vv2 / vel.length);
    const gz = ISO_GROUPS[group] || ISO_GROUPS[1];
    const zone = unit === "arb" ? null
      : vvv <= gz.ab ? "A" : vvv <= gz.bc ? "B" : vvv <= gz.cd ? "C" : "D";

    // پالایش 1X دو پله روی xb
    let fr1 = fr0, a1 = 0;
    for (const [span, steps] of [[0.03, 25], [0.006, 13]]) {
      let bi = 0, ba = -1;
      for (let k = 0; k < steps; k++) {
        const f = fr1 * (1 - span) + 2 * span * fr1 * k / (steps - 1);
        const a = goertzel(xb, fs, f);
        if (a > ba) { ba = a; bi = f; }
      }
      fr1 = bi; a1 = Math.max(a1, ba);
    }

    // معادل‌شتاب: mm/s → ×ωₙ (تا نسبت‌ها مستقل از سنسور شوند)
    const acc = (a, n) => unit === "mm/s" ? a * 2 * Math.PI * n * fr1 : a;

    const orders = { 1: a1 };
    const gridAmp = (fc) => {
      let m = 0;
      for (let k = 0; k < 9; k++)
        m = Math.max(m, goertzel(xb, fs, fc * 0.988 + fc * 0.024 * k / 8));
      return m;
    };
    for (let n = 2; n <= 10; n++)
      orders[n] = (n * fr1 < fhi * 0.98) ? gridAmp(n * fr1) : 0;
    let sub = 0, subF = 0;
    if (fr1 > 5)
      for (let k = 0; k < 17; k++) {
        const f = (0.41 + 0.08 * k / 16) * fr1;
        const a = goertzel(xb, fs, f);
        if (a > sub) { sub = a; subF = f; }
      }
    const aBpf = (blades && fr1 * blades < fhi * 0.98) ? gridAmp(fr1 * blades) : null;

    const findings = [];
    const ref = Math.max(acc(a1, 1), 1e-12);
    let eTot = 1e-15;
    for (const n in orders) eTot += acc(orders[n], n) ** 2;
    const share1 = acc(a1, 1) ** 2 / eTot;
    const lvlZone = zone === "C" ? "warning" : zone === "D" ? "alarm"
                  : zone ? "ok" : "watch";
    if (share1 >= 0.60 && a1 > 0)
      findings.push({ code: "M01", fa: "عدم‌تعادل روتور (1X غالب)",
        level: lvlZone !== "ok" ? lvlZone : "watch",
        detail: `سهم 1X از انرژی مرتبه‌ها: ${(share1*100).toFixed(0)}٪ در ${fr1.toFixed(1)}Hz` });
    const r2 = acc(orders[2], 2) / ref;
    if (r2 >= 0.5)
      findings.push({ code: "M02", fa: "بدترازی/کجی کوپلینگ (2X بالا)",
        level: r2 >= 1.0 ? "alarm" : "warning",
        detail: `2X/1X = ${(r2*100).toFixed(0)}٪ (معادل‌شتاب)` });
    let nH = 0;
    for (let n = 3; n <= 10; n++) if (acc(orders[n], n) > 0.10 * ref) nH++;
    if (nH >= 3)
      findings.push({ code: "M03", fa: "شلی مکانیکی/پای‌لق (هارمونیک‌های متعدد)",
        level: nH >= 5 ? "warning" : "watch",
        detail: `${nH} هارمونیک 3X–10X بالای ۱۰٪ از 1X` });
    const rSub = sub > 0 ? acc(sub, subF / fr1) / ref : 0;
    if (rSub >= 0.25)
      findings.push({ code: "M04", fa: "زیرسنکرون (گرداب/تازیان روغن یا رگلاژ)",
        level: rSub >= 0.5 ? "alarm" : journal ? "warning" : "watch",
        detail: `قله در ${subF.toFixed(1)}Hz = ${(subF/fr1).toFixed(2)}X با دامنه ${(rSub*100).toFixed(0)}٪ از 1X — ${journal ? "یاتاقان صفحه‌ای" : "با یاتاقان صفحه‌ای تطبیق دهید"}` });
    if (aBpf !== null && blades) {
      const rB = acc(aBpf, blades) / ref;
      if (rB >= 0.3)
        findings.push({ code: "M05", fa: `قله گذر پره (${blades} پره)`,
          level: rB >= 1.0 ? "warning" : "watch",
          detail: `BPF = ${(fr1*blades).toFixed(1)}Hz با ${(rB*100).toFixed(0)}٪ از 1X — پره/نازل/رسوب` });
    }
    if (zone === "C")
      findings.push({ code: "Z01", fa: "شدت ویبره ناحیه C (ISO 20816-3)", level: "warning",
        detail: `${vvv.toFixed(2)} mm/s — فقط کوتاه‌مدت مجاز؛ برنامه تعمیر بچینید` });
    else if (zone === "D")
      findings.push({ code: "Z01", fa: "شدت ویبره ناحیه D (خطر آسیب)", level: "alarm",
        detail: `${vvv.toFixed(2)} mm/s — توقف/بازرسی فوری` });
    const L = ["ok", "watch", "warning", "alarm"];
    const worst = findings.reduce((w, f) => L.indexOf(f.level) > L.indexOf(w) ? f.level : w, "ok");
    return { vel_rms: vvv, zone, fr: fr1, orders, sub: [subF, sub],
             bpf: [blades ? blades * fr1 : null, aBpf], share1, findings, worst,
             machine, unit };
  }

  // ═══════ آنالیز حرارتی ادوات نیروگاهی (پورت از thermal_pp.py) ═══════
  const TH_CLASS = { B: [120, 130], F: [140, 155], H: [165, 180] };
  const TH_BRG = [90, 105];
  function thKind(name) {
    const n = (name || "").toLowerCase();
    if (["wind", "coil", "stator", "wdg", "سیم"].some(k => n.indexOf(k) >= 0)) return "winding";
    if (["bear", "brg", "thrust", "pad", "یاتاقان", "بابیت"].some(k => n.indexOf(k) >= 0)) return "bearing";
    return "generic";
  }
  const TH_KIND_FA = { winding: "سیم‌پیچی", bearing: "یاتاقان", generic: "سنسور" };
  function thSlope(t, y) {
    const n = t.length; let mt = 0, my = 0;
    for (let i = 0; i < n; i++) { mt += t[i]; my += y[i]; }
    mt /= n; my /= n;
    let sxy = 0, sxx = 0;
    for (let i = 0; i < n; i++) { sxy += (t[i] - mt) * (y[i] - my); sxx += (t[i] - mt) * (t[i] - mt); }
    return sxx > 1e-12 ? sxy / sxx : 0;
  }
  function analyzeThermal(tIn, sensors, insClass) {
    const t = Float64Array.from(tIn);
    const lim = TH_CLASS[insClass] || TH_CLASS.B;
    const L = ["ok", "watch", "warning", "alarm"];
    const out = [];
    for (const name of Object.keys(sensors)) {
      const y = Float64Array.from(sensors[name]);
      if (y.length < 3) continue;
      const kind = thKind(name);
      const last = y[y.length - 1];
      let mx = -1e300, av = 0;
      for (const v of y) { if (v > mx) mx = v; av += v; }
      av /= y.length;
      const k = Math.max(5, Math.floor(y.length / 3));
      const tt = [], yy = [];
      for (let i = y.length - k; i < y.length; i++) { tt.push(t[i] - t[y.length - k]); yy.push(y[i]); }
      const slope = thSlope(tt, yy) * 3600.0;   // °C/h
      const limw = kind === "winding" ? lim[0] : TH_BRG[0];
      const lima = kind === "winding" ? lim[1] : TH_BRG[1];
      const findings = [];
      let lv = "ok";
      const bump = l => { if (L.indexOf(l) > L.indexOf(lv)) lv = l; };
      if (last >= lima * 0.98) {
        bump("alarm");
        findings.push(`دمای فعلی ${last.toFixed(0)}°C ≥ آستانه خطر ${lima.toFixed(0)}°C`);
      } else if (last >= limw) {
        bump("warning");
        findings.push(`دمای فعلی ${last.toFixed(0)}°C ≥ هشدار ${limw.toFixed(0)}°C`);
      }
      if (slope > 0) {
        if (slope >= 6) bump("warning");
        else if (slope >= 1.5) bump("watch");
        if (slope >= 1.5) findings.push(`نرخ صعود ${slope >= 0 ? "+" : ""}${slope.toFixed(1)}°C/h`);
        const eta = (lima - last) / slope;
        if (eta > 0) {
          if (eta <= 24) { bump("alarm"); findings.push(`زمان تخمینی تا سقف: ${eta.toFixed(0)}h`); }
          else if (eta <= 168) { bump("warning"); findings.push(`زمان تخمینی تا سقف: ${eta.toFixed(0)}h`); }
          else if (eta <= 720) { bump("watch"); findings.push(`زمان تخمینی تا سقف: ${(eta / 24).toFixed(0)} روز`); }
        }
      }
      out.push({ name, kind, kind_fa: TH_KIND_FA[kind],
                 last: +last.toFixed(1), max: +mx.toFixed(1), mean: +av.toFixed(1),
                 slope_h: +slope.toFixed(2), lim_warn: limw, lim_alarm: lima,
                 level: lv, findings });
    }
    const worst = out.reduce((w, s) => L.indexOf(s.level) > L.indexOf(w) ? s.level : w, "ok");
    return { sensors: out, worst, ins_class: insClass };
  }

  // ═══════ آنالیز رله/سه‌فاز فازوری (پورت از relay_pp.py) — ANSI ═══════
  const A_R = [-0.5, Math.sqrt(3) / 2];                        // a = e^{j2π/3}
  function cMul(p, q) { return [p[0] * q[0] - p[1] * q[1], p[0] * q[1] + p[1] * q[0]]; }
  function cAdd(p, q) { return [p[0] + q[0], p[1] + q[1]]; }
  function cDivK(p, k) { return [p[0] / k, p[1] / k]; }
  function cAbs(p) { return Math.hypot(p[0], p[1]); }
  const A_R2 = [Math.cos(4 * Math.PI / 3), Math.sin(4 * Math.PI / 3)];  // a²
  function rPhasor(x, fs, f0m) {           // پورت _phasor: فازور RMS
    const w = 2 * Math.PI * f0m / fs;
    let re = 0, im = 0;
    for (let n = 0; n < x.length; n++) { re += x[n] * Math.cos(w * n); im -= x[n] * Math.sin(w * n); }
    re = 2 * re / x.length / Math.SQRT2; im = 2 * im / x.length / Math.SQRT2;
    return [re, im];
  }
  function analyzeRelay(ch, fs, f0, In, Un) {
    fs = +fs; f0 = +f0 || 50;
    const req = ["ia", "ib", "ic"];
    if (!req.every(k => ch[k])) throw new Error("ستون‌های ia, ib, ic الزامی‌اند.");
    const n0 = Math.min(...req.map(k => ch[k].length));
    const raw = req.map(k => Float64Array.from(ch[k].slice(0, n0)));
    // دقت: mean روی داده خام تا منحنی شبیه python — فاز dc_j
    const means = raw.map(v => { let m = 0; for (const x of v) m += x; return m / v.length; });
    const I = raw.map((v, i) => v.map(x => x - means[i]));
    // فرکانس واقعی: شبکه ±۰٫۵Hz حول f0 — پورت از پایتون
    let f0m = f0;
    if (n0 >= Math.floor(fs)) {
      let best = 0, bi = 0;
      for (let i = 0; i <= 30; i++) {          // دقیقاً linspace(f0-1.5, f0+1.5, 31)
        const g = f0 - 1.5 + 0.1 * i;
        const a = goertzel(I[0], fs, g);
        if (a > best) { best = a; bi = i; }
      }
      f0m = f0 - 1.5 + 0.1 * bi;
    }
    const ph = I.map(v => rPhasor(v, fs, f0m));
    const I0 = cDivK(cAdd(cAdd(ph[0], ph[1]), ph[2]), 3);
    const I1 = cDivK(cAdd(cAdd(ph[0], cMul(A_R, ph[1])), cMul(A_R2, ph[2])), 3);
    const I2 = cDivK(cAdd(cAdd(ph[0], cMul(A_R2, ph[1])), cMul(A_R, ph[2])), 3);
    const I0m = cAbs(I0), I1m = cAbs(I1) + 1e-12, I2m = cAbs(I2);
    const i01 = 3 * I0m;
    const r21 = I2m / I1m;
    const rmsA = I.map(v => { let s = 0; for (const x of v) s += x * x; return Math.sqrt(s / v.length); });
    const peak = Math.max(...rmsA);
    // THD هر فاز (هارمونیک ۲..۷ / فاندیمنتال) درصد بیشینه
    const thds = I.map(v => {
      const a1v = goertzel(v, fs, f0m) + 1e-12;
      let s = 0;
      for (let h = 2; h <= 7; h++) { const g = goertzel(v, fs, h * f0m); s += g * g; }
      return Math.sqrt(s) / a1v;
    });
    const thd = Math.max(...thds) * 100;
    // آفست DC: میانگین خام / پیکِ سیگنال اسمی stack — پورت پایتون (mean(r.x)/max(..|v|))
    let dcmax = 0;
    for (let i = 0; i < 3; i++) {
      let pk = 0; for (const x of I[i]) { const a = Math.abs(x); if (a > pk) pk = a; }
      dcmax = Math.max(dcmax, Math.abs(means[i]) / Math.max(pk, 1e-9));
    }
    // ولتاژ
    const haveV = ["va", "vb", "vc"].every(k => ch[k] && ch[k].length >= n0);
    let v21 = null, vrms = null, vavg = null;
    if (haveV) {
      const pv = ["va", "vb", "vc"].map(k => {
        const v = Float64Array.from(ch[k].slice(0, n0));
        let m = 0; for (const x of v) m += x; m /= v.length;
        return rPhasor(v.map(x => x - m), fs, f0m);
      });
      const V1 = cDivK(cAdd(cAdd(pv[0], cMul(A_R, pv[1])), cMul(A_R2, pv[2])), 3);
      const V2 = cDivK(cAdd(cAdd(pv[0], cMul(A_R2, pv[1])), cMul(A_R, pv[2])), 3);
      v21 = cAbs(V2) / (cAbs(V1) + 1e-12);
      vrms = pv.map(cAbs);
      vavg = (vrms[0] + vrms[1] + vrms[2]) / 3;
    }
    const findings = [];
    const L = ["ok", "watch", "warning", "alarm"];
    const In_eff = In ? +In : peak;
    if (In_eff > 0) {
      const p50 = peak / In_eff;
      if (p50 >= 3.0) findings.push({ code: "50", fa: "اکل اتصال‌کوتاه (آنی)", level: "alarm", detail: `I=${p50.toFixed(1)}×In — رله اتصال‌کوتاه آنی تایید` });
      else if (p50 >= 1.5) findings.push({ code: "50", fa: "اضافه‌جریان بالا (آنی)", level: "warning", detail: `I=${p50.toFixed(1)}×In` });
      else if (p50 >= 1.1 && In) findings.push({ code: "51", fa: "اضافه‌جریان (تاخیری)", level: "watch", detail: `I=${p50.toFixed(1)}×In نامی` });
    }
    if (r21 >= 0.15) findings.push({ code: "46", fa: "توالی منفی بالا (عدم‌تعادل/عیب روتور)", level: "alarm", detail: `I2/I1 = ${(100 * r21).toFixed(0)}٪` });
    else if (r21 >= 0.10) findings.push({ code: "46", fa: "توالی منفی", level: "warning", detail: `I2/I1 = ${(100 * r21).toFixed(0)}٪ (حد ۱۰٪)` });
    const base3 = 0.05 * In_eff;
    if (i01 >= 0.30 * In_eff) findings.push({ code: "59N", fa: "جریان زمین قدرت‌مند (خطای زمین)", level: "alarm", detail: `3I0 = ${(i01 / In_eff * 100).toFixed(0)}٪ In` });
    else if (i01 >= base3 && In) findings.push({ code: "59N", fa: "جریان زمین", level: "warning", detail: `3I0 = ${(i01 / In_eff * 100).toFixed(0)}٪ In` });
    if (haveV && Un) {
      const u2 = +Un;
      if (vavg <= 0.9 * u2) findings.push({ code: "27", fa: "افت ولتاژ (sag)", level: "warning", detail: `V=${(100 * vavg / u2).toFixed(0)}٪ Un` });
      else if (vavg >= 1.1 * u2) findings.push({ code: "59", fa: "افزایش ولتاژ (swell)", level: "warning", detail: `V=${(100 * vavg / u2).toFixed(0)}٪ Un` });
      if (v21 !== null && v21 >= 0.03) findings.push({ code: "47", fa: "عدم‌تعادل ولتاژ", level: v21 >= 0.05 ? "warning" : "watch", detail: `V2/V1 = ${(100 * v21).toFixed(1)}٪ (حد ۳٪)` });
    }
    const df = f0m - f0;
    if (Math.abs(df) >= 0.5) findings.push({ code: "81", fa: "انحراف فرکانس", level: Math.abs(df) < 1.5 ? "warning" : "alarm", detail: `f=${f0m.toFixed(2)}Hz (انحراف ${(df >= 0 ? "+" : "") + df.toFixed(2)}Hz)` });
    if (thd >= 8.0) findings.push({ code: "P01", fa: "THD جریان بالا", level: "watch", detail: `THD=${thd.toFixed(1)}٪` });
    if (dcmax >= 0.10) findings.push({ code: "SAT", fa: "آفست DC (شبه‌اشباع CT)", level: "watch", detail: `مؤلفه DC ≈ ${(100 * dcmax).toFixed(0)}٪ پیک — CT/رکورد را چک کنید` });
    const worst = findings.reduce((w, f) => L.indexOf(f.level) > L.indexOf(w) ? f.level : w, "ok");
    return { f: f0m,
             rms_i: rmsA.map(v => +v.toFixed(3)), peak_i: +peak.toFixed(3),
             phasor_i: { mag: ph.map(p => +cAbs(p).toFixed(3)),
                         ang: ph.map(p => +(Math.atan2(p[1], p[0]) * 180 / Math.PI).toFixed(1)) },
             seq: { I0_mag: +I0m.toFixed(3), I1_mag: +I1m.toFixed(3), I2_mag: +I2m.toFixed(3),
                    i2_over_i1: +(100 * r21).toFixed(1), three_i0: +i01.toFixed(3) },
             vrms: vrms ? vrms.map(v => +v.toFixed(2)) : null,
             v2_over_v1: v21 !== null ? +(100 * v21).toFixed(1) : null,
             thd: +thd.toFixed(1), dc_pct: +(dcmax * 100).toFixed(1),
             findings, worst, In: In_eff };
  }

  // ═══════ COMTRADE (IEEE C37.111) — cfg ASCII + dat ASCII/BINARY (پورت comtrade_reader.py) ═══════
  function ctNorm(s) { return String(s).toLowerCase().replace(/[ (),.\-\/]/g, ""); }
  const CT_I = { ia: ["ia", "ian", "i_a", "ira", "ir", "ila", "la", "ia1"],
                 ib: ["ib", "ibn", "phb", "lb", "ib1"],
                 ic: ["ic", "icn", "phc", "lc", "ic1"] };
  const CT_V = { va: ["va", "van", "uan", "ua", "v1a"],
                 vb: ["vb", "vbn", "ubn", "ub", "v1b"],
                 vc: ["vc", "vcn", "ucn", "uc", "v1c"] };
  function ctMatch(names, kws) {
    const norm = names.map(ctNorm);
    for (const kw of kws) {
      const k2 = ctNorm(kw);
      for (let i = 0; i < norm.length; i++)
        if (norm[i] === k2 || norm[i].endsWith(k2) || norm[i].startsWith(k2)) return i;
    }
    return null;
  }
  function parseComtradeCfg(text) {
    const lines = String(text).split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    const p1 = lines[1].split(",");
    const nA = parseInt(p1[1].replace(/[Aa]/g, ""), 10);
    const nD = p1.length > 2 ? parseInt(p1[2].replace(/[Dd]/g, ""), 10) : 0;
    const chA = [], chD = [];
    let i = 2;
    for (let k = 0; k < nA; k++, i++) {
      const p = lines[i].split(",");
      chA.push({ name: p[1], a: parseFloat(p[5]) || 1, b: parseFloat(p[6]) || 0,
                 ratio: (p.length > 11 && parseFloat(p[11]) !== 0) ? parseFloat(p[10]) / parseFloat(p[11]) : 1,
                 ps: (p[12] || "").trim().toUpperCase() });
    }
    for (let k = 0; k < nD; k++, i++) chD.push({ name: lines[i].split(",")[1] });
    const linef = parseFloat(lines[i]); i += 1;
    const nrates = parseInt(lines[i], 10); i += 1;
    const rates = []; let total = 0;
    for (let k = 0; k < nrates; k++, i++) {
      const r = lines[i].split(",");
      rates.push([parseInt(r[0], 10), parseInt(r[1], 10)]); total = parseInt(r[1], 10);
    }
    i += 1;                                   // timestamp0
    const ft = (lines[i] || "ASCII").trim().toUpperCase();
    return { chA, chD, rates, total, linef, ft, station: lines[0] };
  }
  function parseComtradeDat(dataBuf, cfg) {
    const nA = cfg.chA.length, nD = cfg.chD.length, isBin = cfg.ft.indexOf("BINARY") >= 0;
    const out = cfg.chA.map(() => []);
    if (isBin) {
      const rec = 4 + 4 + 2 * nA + 2 * Math.ceil(nD / 16);
      const v = dataBuf instanceof ArrayBuffer ? new DataView(dataBuf) : dataBuf;
      for (let off = 0; off + rec <= v.byteLength; off += rec)
        for (let j = 0; j < nA; j++)
          out[j].push(v.getInt16(off + 8 + 2 * j, true));
    } else {
      const lines = String(dataBuf).split(/\r?\n/).map(l => l.trim()).filter(Boolean);
      for (const l of lines) {
        const p = l.split(",").map(s => s.trim());
        if (p.length < 2 + nA + nD) continue;
        if (isNaN(parseFloat(p[0]))) continue;
        for (let j = 0; j < nA; j++) out[j].push(parseFloat(p[2 + j]) || 0);
      }
    }
    const res = {};
    cfg.chA.forEach((c, j) => {
      let arr = out[j].map(z => c.a * z + c.b);
      if (c.ps === "S") arr = arr.map(z => z * c.ratio);
      res[c.name] = arr;
    });
    return res;
  }
  function analyzeComtrade(cfgText, datData) {
    const cfg = parseComtradeCfg(cfgText);
    const chA = parseComtradeDat(datData, cfg);
    const names = Object.keys(chA);
    const ch = {};
    for (const [k, mp] of Object.entries(CT_I)) {
      const idx = ctMatch(names, mp);
      if (idx !== null) ch[k] = chA[names[idx]];
    }
    for (const [k, mp] of Object.entries(CT_V)) {
      const idx = ctMatch(names, mp);
      if (idx !== null) ch[k] = chA[names[idx]];
    }
    const fs = cfg.rates[0][0];
    return { ch, fs, meta: cfg };
  }

  // ═══════ پاکسازی نویز محیطی — spectral gating با پروفایل نویز ═══════
  // برای محیط نیروگاه: نویز ایستای زمینه (هوم ترانسفورمر، فن‌ها، ماشین‌های دیگر)
  // الگوریتم: STFT (پنجره Hann، اورلپ ۵۰٪) → تخمین پروفایل نویز از نمونه نویز یا کف صدایی
  // → کاهش طیفی با oversubtraction و کف طیفی → بازسازی ISTFT با OLA.
  // noiseProfile(x, fs, nfft, hop): پروفایل دامنه نویز (آرایه به طول nfft/2)
  function noiseProfile(x, fs, nfft, hop) {
    nfft = nfft || 4096; hop = hop || nfft >> 1;
    const w = new Float64Array(nfft);
    for (let i = 0; i < nfft; i++) w[i] = 0.5 * (1 - Math.cos(2 * Math.PI * i / nfft));
    const re = new Float64Array(nfft), im = new Float64Array(nfft);
    const prof = new Float64Array(nfft >> 1);
    let cnt = 0;
    for (let off = 0; off + nfft <= x.length; off += hop) {
      for (let i = 0; i < nfft; i++) { re[i] = x[off + i] * w[i]; im[i] = 0; }
      fft(re, im);
      for (let k = 1; k < nfft >> 1; k++)
        prof[k] += Math.hypot(re[k], im[k]);
      cnt++;
    }
    if (cnt === 0) return null;
    for (let k = 0; k < nfft >> 1; k++) prof[k] /= cnt;
    return { prof, nfft, hop, fs };
  }

  // noiseClean(x, fs, prof, opts): پاکسازی طیفی (Spectral Gating)
  //   prof: خروجی noiseProfile از ضبط «نویز محیط بدون موتور هدف» — اجباری برای دقت
  //   (حالت null = تخمین خودکار کف نویز، فقط برای برجسته‌سازی ضربه‌ها، برای تون‌های پیوسته مناسب نیست)
  //   opts.alpha: ضریب بیش‌کاهش (پیش‌فرض ۱٫۵) · opts.floor: کف طیفی (۰٫۰۵)
  function noiseClean(xIn, fs, prof, opts) {
    opts = opts || {};
    // در حالت خودکار (بدون پروفایل جدا) کف تخمینی محافظه‌کارتر است → پارامترهای ملایم‌تر
    if (!prof) opts = Object.assign({ alpha: 0.6, floor: 0.5 }, opts);
    const alpha = opts.alpha || 1.2, floor = opts.floor != null ? opts.floor : 0.05;
    const x = Float64Array.from(xIn);
    const nfft = prof ? prof.nfft : 4096, hop = nfft >> 1;
    if (x.length < nfft) return x;
    const w = new Float64Array(nfft);
    for (let i = 0; i < nfft; i++) w[i] = 0.5 * (1 - Math.cos(2 * Math.PI * i / nfft));
    const nb = nfft >> 1;
    // تخمین کف نویز از خود سیگنال (اگر پروفایل نداریم): پرچم مدیان روی فریم‌ها
    let floorMag = null;
    if (!prof) {
      const frames = [];
      const re0 = new Float64Array(nfft), im0 = new Float64Array(nfft);
      for (let off = 0; off + nfft <= x.length; off += hop) {
        for (let i = 0; i < nfft; i++) { re0[i] = x[off + i] * w[i]; im0[i] = 0; }
        fft(re0, im0);
        const m = new Float64Array(nb);
        for (let k = 1; k < nb; k++) m[k] = Math.hypot(re0[k], im0[k]);
        frames.push(m);
      }
      floorMag = new Float64Array(nb);
      const col = new Float64Array(frames.length);
      for (let k = 1; k < nb; k++) {
        for (let f = 0; f < frames.length; f++) col[f] = frames[f][k];
        col.sort();
        floorMag[k] = col[Math.floor(frames.length * 0.25)];  // چارک اول — کف نویز
      }
    } else floorMag = prof.prof;
    // بازسازی با گیت طیفی
    const out = new Float64Array(x.length);
    const wsum = new Float64Array(x.length);
    const re = new Float64Array(nfft), im = new Float64Array(nfft);
    const df = fs / nfft;
    for (let off = 0; off + nfft <= x.length; off += hop) {
      for (let i = 0; i < nfft; i++) { re[i] = x[off + i] * w[i]; im[i] = 0; }
      fft(re, im);
      for (let k = 1; k < nb; k++) {
        const mag = Math.hypot(re[k], im[k]);
        const sub = mag - alpha * floorMag[k];
        const g = sub <= 0 ? floor : Math.max(sub / mag, floor);
        re[k] *= g; im[k] *= g;
        re[nfft - k] = re[k]; im[nfft - k] = -im[k];   // تقارن طیف برای سیگنال حقیقی
      }
      // IFFT با مزدوج‌سازی (مثل analyzer اصلی)
      for (let i = 0; i < nfft; i++) im[i] = -im[i];
      fft(re, im);
      for (let i = 0; i < nfft; i++) {
        out[off + i] += re[i] / nfft * w[i];
        wsum[off + i] += w[i] * w[i];
      }
    }
    // نرمال‌سازی OLA (پنجره Hann با اورلپ ۵۰٪ → جمع مربعات ≈ ثابت)؛ لبه‌ها = سیگنال خام
    for (let i = 0; i < x.length; i++)
      out[i] = wsum[i] > 1e-6 ? out[i] / wsum[i] : x[i];
    return out;
  }

  const API = { BEARINGS, bearingFreqs, analyze, parseCsv, parseWav,
                analyzeCurrent, analyzeMachine, goertzel, ISO_GROUPS,
                analyzeThermal, analyzeRelay, analyzeComtrade,
                parseComtradeCfg, parseComtradeDat,
                noiseClean, noiseProfile };
  G.MMDS_ANALYZE = API;
  if (typeof module !== "undefined" && module.exports) module.exports = API;
})(typeof window !== "undefined" ? window : globalThis);
</script>
<script>
(function(){
  const $ = id => document.getElementById(id);
  const drop = $("drop"), fileIn = $("file");
  const ANALYZE_SUBTITLE = "ستون «vib» یا ستون عددی اول — تا حدود ۲۵۰ هزار نمونه";
  let csvData = null, curData = null, curFs = null, fileName = "", audioMode = false;
  drop.onclick = () => fileIn.click();
  ["dragover","dragenter"].forEach(e => drop.addEventListener(e, ev => {ev.preventDefault(); drop.classList.add("over");}));
  ["dragleave","drop"].forEach(e => drop.addEventListener(e, ev => {ev.preventDefault(); drop.classList.remove("over");}));
  drop.addEventListener("drop", ev => { const f = ev.dataTransfer.files[0]; if (f) load(f); });
  fileIn.onchange = () => { if (fileIn.files[0]) load(fileIn.files[0]); };
  const AUDIO_EXT = /\.(wav|mp3|m4a|aac|ogg)$/i;
  function markLoaded(title, sub){
    drop.querySelector("b").textContent = title;
    drop.querySelector(".sub").textContent = sub;
  }
  function load(f){
    fileName = f.name;
    if (AUDIO_EXT.test(f.name)) {                 // ─── فایل صوتی ───
      const rd = new FileReader();
      rd.onload = async () => {
        try {
          let samples, sr;
          if (/\.wav$/i.test(f.name)) {
            const w = MMDS_ANALYZE.parseWav(rd.result);
            samples = Array.from(w.samples); sr = w.sampleRate;
          } else {                                // mp3/m4a/ogg → Web Audio API
            const AC = window.AudioContext || window.webkitAudioContext;
            const ctxA = new AC();
            const ab = await ctxA.decodeAudioData(rd.result.slice(0));
            sr = ab.sampleRate; samples = Array.from(ab.getChannelData(0));
          }
          csvData = samples; audioMode = true;
          $("fs").value = sr; $("fs").disabled = true;
          markLoaded(`🎵 ${f.name}`, `فایل صوتی — fs=${sr.toLocaleString("fa-IR")}Hz از خود فایل · ${samples.length.toLocaleString("fa-IR")} نمونه`);
        } catch (e) { alert("خواندن فایل صوتی ممکن نشد: " + e.message); }
      };
      rd.readAsArrayBuffer(f);
      return;
    }
    const rd = new FileReader();                  // ─── CSV ───
    rd.onload = () => {
      csvData = MMDS_ANALYZE.parseCsv(rd.result); audioMode = false;
      $("fs").disabled = false;
      markLoaded(`✔ ${f.name}`, `${csvData.length.toLocaleString("fa-IR")} نمونه خوانده شد — آماده آنالیز`);
    };
    rd.readAsText(f);
  }
  // ── کانال جریان (اختیاری) ──
  function loadAny(f, cb){
    if (AUDIO_EXT.test(f.name)){
      const rd = new FileReader();
      rd.onload = async () => {
        try {
          let samples, sr;
          if (/\.wav$/i.test(f.name)) { const w = MMDS_ANALYZE.parseWav(rd.result); samples = Array.from(w.samples); sr = w.sampleRate; }
          else { const AC = window.AudioContext || window.webkitAudioContext;
                 const cx = new AC(); const ab = await cx.decodeAudioData(rd.result.slice(0));
                 sr = ab.sampleRate; samples = Array.from(ab.getChannelData(0)); }
          cb(samples, sr);
        } catch(e){ alert("خواندن فایل ممکن نشد: " + e.message); }
      };
      rd.readAsArrayBuffer(f);
    } else {
      const rd = new FileReader();
      rd.onload = () => cb(MMDS_ANALYZE.parseCsv(rd.result), null);
      rd.readAsText(f);
    }
  }
  $("file-cur").onchange = () => {
    const f = $("file-cur").files[0]; if (!f) return;
    loadAny(f, (samples, sr) => {
      curData = samples; curFs = sr || parseFloat($("fs-cur").value) || 10240;
      if (sr) $("fs-cur").value = sr;
      const lbl = $("file-cur");
      lbl.style.color = "#6ee7b7";
      lbl.title = `${f.name} — ${samples.length.toLocaleString("fa-IR")} نمونه`;
    });
  };

  // ══════ حالت پلاک موتور ══════
  $("np-apply").onclick = () => {
    const p = parseInt($("np-p").value), f = parseFloat($("np-f").value);
    const nr = parseFloat($("np-rpm").value), kw = parseFloat($("np-kw").value);
    if (!(nr > 0)){ alert("سرعت نامی را از روی پلاک وارد کن."); return; }
    const ns = 120 * f / p;
    if (nr >= ns){ alert(`سرعت نامی ${nr} از سنکرون ${ns} بیشتر است — قطب یا پلاک اشتباه.`); return; }
    const s = (ns - nr) / ns;
    $("nss").value = ns;
    $("rpm").value = nr;
    $("np-out").innerHTML = `✔ ns=<b>${ns.toLocaleString("fa-IR")}rpm</b> · لغزش نامی s=<b>${(s*100).toFixed(1)}٪</b>` +
      ` · سایدبند میله‌شکسته در ${(f*(1-2*s)).toFixed(1)} و ${(f*(1+2*s)).toFixed(1)}Hz جست‌وجو می‌شود` +
      (kw ? ` · جریان اسمی تخمینی ≈ <b>${(1000*kw/(Math.sqrt(3)*400*0.85*0.85)).toFixed(1)}A</b> (ولتاژ۴۰۰، η=cosφ=0.85)` : "") +
      ` — «آنالیز کن» را بزنید.`;
    if (kw > 0) $("qc-in").value = (1000 * kw / (Math.sqrt(3) * 400 * 0.85 * 0.85)).toFixed(1);
  };

  // ══════ چک سریع انبری (فقط RMS) ══════
  $("qc-go").onclick = () => {
    const vals = ["qc-i1", "qc-i2", "qc-i3"].map(id => parseFloat($(id).value)).filter(v => v > 0);
    const In = parseFloat($("qc-in").value), out = $("qc-out");
    if (!vals.length){ out.textContent = "حداقل یک عدد جریان وارد کن."; return; }
    const avg = vals.reduce((a, b) => a + b, 0) / vals.length;
    const lines = [];
    if (In > 0){
      const load = avg / In * 100;
      lines.push(`🔋 بار موتور ≈ <b>${load.toFixed(0)}٪</b> نامی (${avg.toFixed(1)}A از ${In}A)` +
        (load > 115 ? " — 🔴 اضافه‌بار!" : load > 100 ? " — 🟠 نزدیک سقف نامی" :
         load < 30 ? " — 🟡 بار کم؛ ضبط MCSA با این بار نامعتبر است (≥۳۰٪ لازم)" : " — ✓ محدوده مناسب برای ضبط"));
    } else lines.push("ℹ️ جریان نامی ندادی — ٪بار محاسبه نشد (حالت 🏷️ پلاک را اعمال کن تا خودکار پر شود).");
    if (vals.length === 3){
      const dev = Math.max(...vals.map(v => Math.abs(v - avg))) / avg * 100;
      lines.push(`⚖️ عدم‌تعادل جریان: <b>${dev.toFixed(1)}٪</b>` +
        (dev > 10 ? " — 🔴 بحرانی؛ علت (عدم‌تعادل ولتاژ/سیم‌پیچی/اتصالات) را بررسی کن" :
         dev > 6 ? " — 🟡 بالاتر از حد معمول ۶٪؛ ولتاژ فازها را هم چک کن" : " — ✓ متعادل"));
      lines.push("💡 عدم‌تعادل جریان معمولاً ۶–۱۰ برابر عدم‌تعادل ولتاژ شبکه است.");
    } else if (vals.length === 2){
      lines.push("ℹ️ برای چک عدم‌تعادل، هر سه فاز را وارد کن.");
    }
    out.innerHTML = lines.join("<br>");
  };

  // ══════ تحلیل ویبره ماشین دوار (ISO 20816-3) ══════
  $("mv-go").onclick = () => {
    if (!csvData || csvData.length < 2000){ alert("اول فایل/ضبط ارتعاش را بارگیری کن."); return; }
    const fs = parseFloat($("fs").value), rpm = parseFloat($("rpm").value);
    if (!(fs > 0) || !(rpm > 0)){ alert("fs و rpm را درست وارد کن."); return; }
    $("mv-go").innerHTML = '<span class="spin"></span>'; $("mv-go").disabled = true;
    setTimeout(() => {
      const r = MMDS_ANALYZE.analyzeMachine(csvData, fs, rpm,
        parseInt($("mv-blad").value) || 0, $("mv-unit").value,
        parseInt($("mv-grp").value), $("mv-jrnl").value === "y", $("mv-mach").value);
      const out = $("mv-out"), FA = n => Number(n).toLocaleString("fa-IR", {maximumFractionDigits: 2});
      const zc = r.zone ? { A: "#34d399", B: "#34d399", C: "#fbbf24", D: "#fb7185" }[r.zone] : "#7c8fb3";
      let h = `<div class="metrics" style="grid-template-columns:repeat(${r.zone ? 4 : 3},1fr);margin:10px 0">` +
        `<div class="metric"><div class="v">${FA(r.vel_rms)}${r.unit === "arb" ? "*" : " mm/s"}</div><div class="l">سرعت RMS (۱۰–۱۰۰۰Hz)</div></div>` +
        (r.zone ? `<div class="metric" style="border-color:${zc}"><div class="v" style="color:${zc}">Zone ${r.zone}</div><div class="l">ISO 20816-3</div></div>` : `<div class="metric"><div class="v">—</div><div class="l">Zone (نیازمند کالیبراسیون)</div></div>`) +
        `<div class="metric"><div class="v">${FA(r.fr)}Hz</div><div class="l">1X (${FA(r.fr*60)} rpm)</div></div>` +
        `<div class="metric"><div class="v">${r.sub[0] ? (r.sub[0]/r.fr).toFixed(2)+"X" : "—"}</div><div class="l">زیرسنکرون</div></div></div>`;
      h += r.findings.length
        ? r.findings.map(f => `<div style="font-size:13.5px;color:var(--mut)">• <b style="color:${f.level === "alarm" ? "var(--bad)" : f.level === "warning" ? "var(--warn)" : "var(--acc2)"}">[${f.code}] ${f.fa}</b> — ${f.detail}</div>`).join("")
        : `<div style="font-size:13.5px;color:var(--ok)">✓ الگوی مرتبه‌ای عادی — 2X پائین، هارمونیک کم، بدون زیرسنکرون قدرت‌مند</div>`;
      if (r.unit === "arb")
        h += `<div class="hint" style="margin-top:6px">* واحد نامشخص: عدد سرعت فقط نسبی است؛ نسبت‌های X و تشخیص الگو معتبرند، Zone نه.</div>`;
      out.innerHTML = h;
      $("mv-go").innerHTML = "⚙️ تحلیل ویبره"; $("mv-go").disabled = false;
    }, 30);
  };

  // ══════ 🔥 آنالیز حرارتی (روند DCS) ══════
  function parseThermalCsv(text, dtS){
    const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    if (!lines.length) return null;
    const head = lines[0].split(/[;,\t]/).map(s => s.trim());
    const rows = lines.slice(1).map(l => l.split(/[;,\t]/).map(s => s.trim())).filter(r => r.length >= head.length);
    if (rows.length < 3) return null;
    let time = [], tIsDate = false;
    time = rows.map(r => { const d = Date.parse(r[0]); return isNaN(d) ? null : d / 1000; });
    tIsDate = time.every(v => v !== null);
    if (!tIsDate){
      time = rows.map(r => parseFloat(r[0])).map(v => isNaN(v) ? null : v);
      if (time.some(v => v === null)) { time = rows.map((_, i) => i * dtS); }
    }
    const t0 = time[0]; time = time.map(v => v - t0);
    const sensors = {};
    for (let c = 1; c < head.length; c++){
      const vals = rows.map(r => parseFloat((r[c] || "").replace(",", ".")));
      const good = vals.filter(v => !isNaN(v));
      if (good.length >= 3) sensors[head[c]] = vals.map(v => isNaN(v) ? good[0] : v);
    }
    return { time, sensors };
  }
  $("th-go").onclick = () => {
    const f = $("th-file").files[0];
    if (!f){ alert("اول فایل روند CSV را انتخاب کن."); return; }
    const out = $("th-out");
    out.innerHTML = '<span class="spin"></span> خواندن…';
    const rd = new FileReader();
    rd.onload = () => {
      const dt = parseFloat($("th-dt").value) || 3600;
      const parsed = parseThermalCsv(rd.result, dt);
      if (!parsed || !Object.keys(parsed.sensors).length){
        out.innerHTML = `<span style="color:var(--warn)">⚠ ستون عددی کافی پیدا نشد — ستون اول زمان، بقیه دمای سنسورها باشد (حداقل ۳ ردیف داده).</span>`; return;
      }
      const r = MMDS_ANALYZE.analyzeThermal(parsed.time, parsed.sensors, $("th-cls").value);
      const EC = { ok: "var(--ok)", watch: "var(--acc2)", warning: "var(--warn)", alarm: "var(--bad)" };
      const EM = { ok: "⚪", watch: "🟢", warning: "🟡", alarm: "🔴" };
      const FA = n => Number(n).toLocaleString("fa-IR", {maximumFractionDigits: 2});
      let h = `<div class="sub" style="font-weight:700;color:${EC[r.worst]};margin:6px 0">${EM[r.worst]} بدترین وضعیت: ${({ok:"سالم",watch:"تحت پایش",warning:"هشدار",alarm:"بحرانی"})[r.worst]} — ${Object.keys(parsed.sensors).length} سنسور</div>`;
      for (const s of r.sensors){
        h += `<div style="font-size:13.5px;border-right:3px solid ${EC[s.level]};padding-right:8px;margin:6px 0;color:var(--mut)">` +
          `<b style="color:${EC[s.level]}">${EM[s.level]} ${s.name}</b> <span style="color:var(--txt)">(${s.kind_fa})</span> — آخر: <b>${FA(s.last)}°C</b> | میانگین ${FA(s.mean)} | بیشینه ${FA(s.max)} | شیب ${s.slope_h >= 0 ? "+" : ""}${FA(s.slope_h)}°C/h سقف هشدار ${s.lim_warn}°C / خطر ${s.lim_alarm}°C`;
        if (s.findings.length) h += "<br>• " + s.findings.join("<br>• ");
        h += "</div>";
      }
      h += `<div class="hint" style="margin-top:6px">آستانه‌ها: یاتاقان بابیت ۹۰/۱۰۵°C · سیم‌پیچی کلاس ${r.ins_class}: ${r.ins_class === "B" ? "۱۲۰/۱۳۰" : r.ins_class === "F" ? "۱۴۰/۱۵۵" : "۱۶۵/۱۸۰"}°C — صعود سریع (>۶°C/h) یعنی عیب حاد — شیب ملایم مثبت یعنی فرسایش تدریجی.</div>`;
      out.innerHTML = h;
    };
    rd.readAsText(f);
  };

  // ══════ ⚡ آنالیز سه‌فاز/رله (فازور + ANSI) ══════
  $("rl-go").onclick = () => {
    const f = $("rl-file").files[0], fc = $("rl-cfg").files[0], fd = $("rl-dat").files[0];
    const out = $("rl-out");
    const fs0 = parseFloat($("rl-fs").value);
    if (!f && !(fc && fd)){ alert("اول فایل CSV یا هر دو .cfg+.dat COMTRADE را انتخاب کن."); return; }
    out.innerHTML = '<span class="spin"></span> خواندن…';
    const finish = (r, note) => {
      const EC = { ok: "var(--ok)", watch: "var(--acc2)", warning: "var(--warn)", alarm: "var(--bad)" };
      const EM = { ok: "⚪", watch: "🟢", warning: "🟡", alarm: "🔴" };
      const FA = n => Number(n).toLocaleString("fa-IR", {maximumFractionDigits: 2});
      let h = `<div class="sub" style="font-weight:700;color:${EC[r.worst]};margin:8px 0">${EM[r.worst]} وضعیت: ${({ok:"سالم و متعادل",watch:"نیازمند پایش",warning:"هشدار — بررسی سریع",alarm:"بحرانی — کنترل فوری"})[r.worst]} (f=${FA(r.f)}Hz${note || ""})</div>`;
      h += `<div class="metrics" style="grid-template-columns:repeat(4,1fr);margin:8px 0">` +
        `<div class="metric"><div class="v">${r.rms_i.map(v => FA(v)).join(" / ")}</div><div class="l">جریان RMS فازها (A)</div></div>` +
        `<div class="metric"><div class="v">${FA(r.seq.i2_over_i1)}٪</div><div class="l">توالی منفی I2/I1</div></div>` +
        `<div class="metric"><div class="v">${FA(r.seq.three_i0)}</div><div class="l">3I₀ زمین (A)</div></div>` +
        `<div class="metric"><div class="v">${FA(r.thd)}٪</div><div class="l">THD جریان</div></div></div>`;
      if (r.vrms) h += `<div style="font-size:13.5px;color:var(--mut);margin:4px 0">ولتاژ فازها: ${r.vrms.map(v => FA(v)).join(" / ")}V${r.v2_over_v1 !== null ? ` · عدم‌تعادل ولتاژ V2/V1 = <b>${FA(r.v2_over_v1)}٪</b>` : ""}</div>`;
      h += `<div style="font-size:13.5px;color:var(--mut);margin:4px 0">زاویه فازوز جریان: فاز a ${r.phasor_i.ang[0].toFixed(1)}° · b ${r.phasor_i.ang[1].toFixed(1)}° · c ${r.phasor_i.ang[2].toFixed(1)}° (باید ±۱۲۰° باشد)</div>`;
      if (r.findings.length)
        h += r.findings.map(f => `<div style="font-size:13.5px;color:var(--mut);margin:4px 0">• <b style="color:${EC[f.level]}">${EM[f.level]} [${f.code}] ${f.fa}</b> — ${f.detail}</div>`).join("");
      else
        h += `<div style="font-size:13.5px;color:var(--ok);margin:6px 0">✓ بدون یافته ANSI — سیستم متعادل</div>`;
      h += `<div class="hint" style="margin-top:8px">⚠ بدون In واقعی، نسبت «×In» به بزرگ‌ترین فاز خود فایل است.</div>`;
      out.innerHTML = h;
    };
    if (fc && fd){
      const rdc = new FileReader();
      rdc.onload = () => {
        const cfgText = rdc.result;
        const meta = MMDS_ANALYZE.parseComtradeCfg ? MMDS_ANALYZE.parseComtradeCfg(cfgText) : null;
        const rdd = new FileReader();
        rdd.onload = () => {
          const isBin = meta && meta.ft.indexOf("BINARY") >= 0;
          const dat = isBin ? rdd.result : String(rdd.result);
          const pr = MMDS_ANALYZE.analyzeComtrade(cfgText, dat);
          if (!pr.ch.ia || !pr.ch.ib || !pr.ch.ic){
            out.innerHTML = `<span style="color:var(--warn)">⚠ کانال‌های جریان ia/ib/ic در cfg پیدا نشد. کانال‌ها: ${Object.keys(pr.meta ? pr : {}).join(", ")}</span>`; return;
          }
          const r = MMDS_ANALYZE.analyzeRelay(pr.ch, pr.fs, parseFloat($("rl-f0").value) || 50,
            parseFloat($("rl-in").value) || null, parseFloat($("rl-un").value) || null);
          finish(r, ` · ${pr.meta.station.split(",")[0]} · fs=${pr.fs}Hz · ${pr.meta.ft}`);
        };
        rdd.onerror = () => out.innerHTML = `<span style="color:var(--warn)">⚠ خطا در خواندن .dat</span>`;
        if (meta && meta.ft.indexOf("BINARY") >= 0) rdd.readAsArrayBuffer(fd);
        else rdd.readAsText(fd);
      };
      rdc.readAsText(fc);
      return;
    }
    const rd = new FileReader();
    rd.onload = () => {
      const lines = String(rd.result).split(/\r?\n/).map(l => l.trim()).filter(Boolean);
      if (lines.length < 30){ out.innerHTML = `<span style="color:var(--warn)">⚠ داده کافی نیست (حداقل ۳۰ نمونه).</span>`; return; }
      const head = lines[0].split(/[;,\t]/).map(s => s.trim().toLowerCase());
      const col = n => head.indexOf(n);
      const get = n => { const c = col(n); if (c < 0) return null; return lines.slice(1).map(l => parseFloat((l.split(/[;,\t]/)[c] || "").replace(",", "."))).filter(v => !isNaN(v)); };
      const ch = { ia: get("ia"), ib: get("ib"), ic: get("ic"), va: get("va"), vb: get("vb"), vc: get("vc") };
      if (!ch.ia || !ch.ib || !ch.ic){
        out.innerHTML = `<span style="color:var(--warn)">⚠ ستون‌های <b>ia, ib, ic</b> (سرستون lowercase) پیدا نشد. ستون‌ها: ${head.join(", ")}</span>`; return;
      }
      const r = MMDS_ANALYZE.analyzeRelay(ch, fs0, parseFloat($("rl-f0").value) || 50,
        parseFloat($("rl-in").value) || null, parseFloat($("rl-un").value) || null);
      const EC = { ok: "var(--ok)", watch: "var(--acc2)", warning: "var(--warn)", alarm: "var(--bad)" };
      const EM = { ok: "⚪", watch: "🟢", warning: "🟡", alarm: "🔴" };
      const FA = n => Number(n).toLocaleString("fa-IR", {maximumFractionDigits: 2});
      let h = `<div class="sub" style="font-weight:700;color:${EC[r.worst]};margin:8px 0">${EM[r.worst]} وضعیت: ${({ok:"سالم و متعادل",watch:"نیازمند پایش",warning:"هشدار — بررسی سریع",alarm:"بحرانی — کنترل فوری"})[r.worst]} (f=${FA(r.f)}Hz)</div>`;
      h += `<div class="metrics" style="grid-template-columns:repeat(4,1fr);margin:8px 0">` +
        `<div class="metric"><div class="v">${r.rms_i.map(v => FA(v)).join(" / ")}</div><div class="l">جریان RMS فازها (A)</div></div>` +
        `<div class="metric"><div class="v">${FA(r.seq.i2_over_i1)}٪</div><div class="l">توالی منفی I2/I1</div></div>` +
        `<div class="metric"><div class="v">${FA(r.seq.three_i0)}</div><div class="l">3I₀ زمین (A)</div></div>` +
        `<div class="metric"><div class="v">${FA(r.thd)}٪</div><div class="l">THD جریان</div></div></div>`;
      if (r.vrms) h += `<div style="font-size:13.5px;color:var(--mut);margin:4px 0">ولتاژ فازها: ${r.vrms.map(v => FA(v)).join(" / ")}V${r.v2_over_v1 !== null ? ` · عدم‌تعادل ولتاژ V2/V1 = <b>${FA(r.v2_over_v1)}٪</b>` : ""}</div>`;
      h += `<div style="font-size:13.5px;color:var(--mut);margin:4px 0">زاویه فازوز جریان: فاز a ${r.phasor_i.ang[0].toFixed(1)}° · b ${r.phasor_i.ang[1].toFixed(1)}° · c ${r.phasor_i.ang[2].toFixed(1)}° (باید ±۱۲۰° باشد)</div>`;
      if (r.findings.length)
        h += r.findings.map(f => `<div style="font-size:13.5px;color:var(--mut);margin:4px 0">• <b style="color:${EC[f.level]}">${EM[f.level]} [${f.code}] ${f.fa}</b> — ${f.detail}</div>`).join("");
      else
        h += `<div style="font-size:13.5px;color:var(--ok);margin:6px 0">✓ بدون یافته ANSI — سیستم متعادل (توالی منفی ≈ صفر، بدون سفر جریان/زمین/فرکانس)</div>`;
      h += `<div class="hint" style="margin-top:8px">⚠ بدون In واقعی، نسبت «×In» به بزرگ‌ترین فاز خود فایل است. برای رکورد COMTRADE از خروجی CSV نرم‌افزار رله (Siemens DIGSI / ABB PCM600 / MiCOM) استفاده کنید و سرستون‌ها را lowercase کنید.</div>`;
      out.innerHTML = h;
    };
    rd.readAsText(f);
  };

  // ══════ ضبط زنده (getUserMedia) ══════
  async function fillInputs(){
    try{
      await navigator.mediaDevices.getUserMedia({audio: true});   // درخواست مجوز برای خواندن label
      const ds = await navigator.mediaDevices.enumerateDevices();
      const sel = $("rec-in");
      if (sel.options.length > 1) return;
      for (const d of ds) if (d.kind === "audioinput"){
        const o = document.createElement("option");
        o.value = d.deviceId; o.textContent = d.label || "ورودی " + (sel.options.length);
        sel.appendChild(o);
      }
    }catch(e){}
  }
  fillInputs();
  let recStream = null, recTimer = null, stopRecording = null;
  $("rec-btn").onclick = async () => {
    if (stopRecording){ stopRecording(); return; }
    const stat = $("rec-stat"), fill = $("rec-fill"), btn = $("rec-btn");
    const selectedDur = parseInt($("rec-dur").value, 10);
    const ch = $("rec-ch").value;
    const minDur = ch === "cur" ? 30 : 15;
    const dur = Math.max(selectedDur, minDur);
    try{
      stat.textContent = "در حال درخواست مجوز میکروفون…";
      const cstr = { audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false, channelCount: 1 } };
      if ($("rec-in").value) cstr.audio.deviceId = { exact: $("rec-in").value };
      recStream = await navigator.mediaDevices.getUserMedia(cstr);
      const AC = window.AudioContext || window.webkitAudioContext;
      const actx = new AC();
      const src = actx.createMediaStreamSource(recStream);
      const proc = actx.createScriptProcessor(4096, 1, 1);
      const chunks = []; let n = 0, maxAbs = 0;
      proc.onaudioprocess = (ev) => {
        const buf = ev.inputBuffer.getChannelData(0);
        chunks.push(new Float32Array(buf)); n += buf.length;
        for (let i = 0; i < buf.length; i++){ const a = Math.abs(buf[i]); if (a > maxAbs) maxAbs = a; }
      };
      src.connect(proc); proc.connect(actx.destination);
      const t0 = performance.now();
      const channelName = ch === "cur" ? "⚡ جریان" : "📳 ارتعاش/صوت";
      btn.disabled = true; btn.textContent = `⏺ ضبط… توقف پس از ${minDur} ثانیه`;
      stat.textContent = `حداقل ضبط برای ${ch === "cur" ? "جریان" : "ارتعاش/صوت"}: ${minDur} ثانیه؛ پس از آن می‌توانید متوقف کنید. بار موتور را ثابت نگه دارید.`;
      let finished = false;
      function finish(manual = false){
        if (finished) return;
        finished = true;
        if (recTimer){ clearInterval(recTimer); recTimer = null; }
        stopRecording = null;
        proc.disconnect(); src.disconnect(); recStream.getTracks().forEach(t => t.stop());
        const fsr = actx.sampleRate || 48000;
        actx.close(); recStream = null;
        const elapsed = (performance.now() - t0) / 1000;
        const x = new Float64Array(n); let o = 0;
        for (const c of chunks){ x.set(c, o); o += c.length; }
        btn.disabled = false; btn.textContent = "⏺ شروع ضبط";
        fill.style.width = Math.min(100, elapsed / dur * 100) + "%";
        if (manual) stat.textContent = `ضبط ${channelName} در ${Math.floor(elapsed)} ثانیه متوقف شد؛ در حال آماده‌سازی تحلیل…`;
        if (maxAbs < 0.005){ stat.textContent = "❌ سیگنال دریافت نشد — ورودی را چک کن (TRRS گوشی برای جریان مناسب نیست!)."; return; }
        const arr = Array.from(x);
        if (ch === "cur"){
          curData = arr; curFs = fsr; $("fs-cur").value = fsr;
          // کنترل کیفیت: مؤلفه ۵۰Hz باید غالب باشد — وگرنه ورودی اشتباه/فیلترشده است
          const g50 = MMDS_ANALYZE.goertzel(arr, fsr, 50);
          let rI = 0; for (let v of arr) rI += v * v; rI = Math.sqrt(rI / arr.length);
          const f1r = g50 / (rI * 1.414 + 1e-12);
          let q = `✔ ${n.toLocaleString("fa-IR")} نمونه جریان @ ${fsr.toLocaleString("fa-IR")}Hz — سهم ۵۰Hz: ${(f1r*100).toFixed(0)}٪ — <b>«آنالیز کن»</b> را بزنید.`;
          if (f1r < 0.25)
            q += `<br>⚠️ <span style="color:var(--warn)">مؤلفه ۵۰Hz ضعیف است؛ ورودی آیا TRRS گوشی/های‌پس‌شده است؟ فقط Line-in/کارت‌صدای USB.</span>`;
          stat.innerHTML = q;
        } else {
          csvData = arr; $("fs").value = fsr; audioMode = true;
          markLoaded("🎙️ ضبط زنده صوت", `${n.toLocaleString("fa-IR")} نمونه @ ${fsr.toLocaleString("fa-IR")}Hz — آماده آنالیز`);
          stat.innerHTML = `✔ ضبط تکمیل شد — <b>«آنالیز کن»</b> را بزنید.`;
        }
      }
      stopRecording = () => {
        if (!finished && (performance.now() - t0) / 1000 >= minDur) finish(true);
      };
      recTimer = setInterval(() => {
        const el = (performance.now() - t0) / 1000;
        fill.style.width = Math.min(100, el / dur * 100) + "%";
        btn.disabled = el < minDur;
        btn.textContent = el < minDur ? `⏺ ضبط… ${Math.ceil(minDur - el)} ثانیه تا توقف` : "⏹ توقف و تحلیل";
        stat.textContent = `ضبط ${channelName}: ${Math.floor(el)} از ${dur} ثانیه — حداکثر سطح ${(maxAbs*100).toFixed(0)}٪` +
          (maxAbs > 0.95 ? " ⚠️ اشباع! دامنه را کم کن." : maxAbs < 0.01 && el > 3 ? " ⚠️ ورودی سکوت است — کابل را چک کن." : "");
        if (el >= dur) finish();
      }, 200);
    }catch(e){
      stat.textContent = "❌ " + (e.name === "NotAllowedError" ? "دسترسی میکروفون رد شد — مجوز را در مرورگر فعال کن." :
              e.name === "NotFoundError" ? "هیچ ورودی صوتی پیدا نشد." : e.message);
    }
  };

  $("go").onclick = () => {
    const hasVib = csvData && csvData.length >= 2000;
    const hasCur = curData && curData.length > 5000;
    if (!hasVib && !hasCur){ alert("اول داده بده: فایل CSV/صوتی ارتعاش، یا فایل/ضبط جریان."); return; }
    const fs = parseFloat($("fs").value), rpm = parseFloat($("rpm").value);
    const brg = MMDS_ANALYZE.BEARINGS[$("brg").value];
    if (hasVib && (!(fs > 0) || !(rpm > 0) || !brg)){ alert("fs و rpm را درست وارد کن."); return; }
    // پاکسازی نویز محیط (اگر روشن باشد)
    const nzMode = $("nz-mode").value;
    const nzAlpha = parseFloat($("nz-alpha").value) || 1.5;
    let csvClean = csvData, curClean = curData, nzMsg = "";
    if (nzMode !== "off"){
      try{
        const prof = (nzMode === "prof" && nzProf) ? nzProf : null;
        const fsV = hasVib ? fs : 0;
        if (hasVib) csvClean = Array.from(MMDS_ANALYZE.noiseClean(csvData, fsV, prof, { alpha: nzAlpha }));
        if (hasCur && curFs) curClean = Array.from(MMDS_ANALYZE.noiseClean(curData, curFs, prof, { alpha: nzAlpha }));
        nzMsg = prof ? "🧹 با پروفایل نویز محیط" : "🧹 خودکار (کف نویز)";
      }catch(e){ nzMsg = "⚠️ پاکسازی نشد: " + e.message; }
    }
    $("go").innerHTML = '<span class="spin"></span> در حال تحلیل…'; $("go").disabled = true;
    setTimeout(() => {
      let r = null, rCur = null;
      if (hasVib) r = MMDS_ANALYZE.analyze(csvClean, fs, rpm, brg, { kind: audioMode ? "ac" : "vib" });
      if (hasCur){
        const nss = parseFloat($("nss").value) || 1500;
        const slip = Math.min(Math.max((nss - rpm) / nss, 0.002), 0.3);
        rCur = MMDS_ANALYZE.analyzeCurrent(curClean, curFs || fs, 50, slip, rpm / 60);
      }
      render(r, csvClean, fs, rCur, nzMsg); $("go").innerHTML = "🔍 آنالیز کن"; $("go").disabled = false;
    }, 30);
  };
  const FA = n => Number(n).toLocaleString("fa-IR", {maximumFractionDigits: 1});
  const LV_ORDER = ["ok", "watch", "warning", "alarm"];

  // 🧹 ضبط نمونه نویز محیط (۳ ثانیه) → پروفایل طیفی برای پاکسازی
  let nzProf = null;
  $("nz-btn").onclick = async () => {
    const btn = $("nz-btn"), st = $("nz-stat");
    try{
      st.textContent = "در حال درخواست مجوز میکروفون…";
      const cstr = { audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false, channelCount: 1 } };
      if ($("rec-in").value) cstr.audio.deviceId = { exact: $("rec-in").value };
      const stream = await navigator.mediaDevices.getUserMedia(cstr);
      const AC = window.AudioContext || window.webkitAudioContext;
      const actx = new AC();
      const src = actx.createMediaStreamSource(stream);
      const proc = actx.createScriptProcessor(4096, 1, 1);
      const chunks = []; let n = 0;
      proc.onaudioprocess = (ev) => { const b = ev.inputBuffer.getChannelData(0); chunks.push(new Float32Array(b)); n += b.length; };
      src.connect(proc); proc.connect(actx.destination);
      btn.disabled = true; btn.textContent = "🔇 در حال ضبط نویز…";
      st.textContent = "۳ ثانیه فقط صدای محیط را ضبط می‌کنیم — موتور هدف را ساکت/بعید نگه دار.";
      await new Promise(res => setTimeout(res, 3000));
      proc.disconnect(); src.disconnect(); stream.getTracks().forEach(t => t.stop());
      const fsr = actx.sampleRate || 48000; actx.close();
      const x = new Float64Array(n); let o = 0;
      for (const c of chunks){ x.set(c, o); o += c.length; }
      let mx = 0; for (const v of x) mx = Math.max(mx, Math.abs(v));
      if (mx < 0.005){ st.textContent = "❌ صدای محیط دریافت نشد — میکروفون را چک کن."; btn.disabled = false; btn.textContent = "🔇 ضبط نمونه نویز (۳ثانیه)"; return; }
      nzProf = MMDS_ANALYZE.noiseProfile(x, fsr);
      nzProf.fs = fsr;   // همراه پروفایل نگه می‌داریم
      $("nz-mode").value = "prof";
      st.innerHTML = `✔ نمونه نویز ثبت شد (${(n/1000).toFixed(0)} هزار نمونه @ ${fsr.toLocaleString("fa-IR")}Hz) — حالت پاکسازی: <b>دقیق</b>. حالا موتور را ضبط و آنالیز کن.`;
      btn.disabled = false; btn.textContent = "🔇 ضبط مجدد نمونه نویز";
    }catch(e){
      st.textContent = "❌ " + (e.name === "NotAllowedError" ? "دسترسی میکروفون رد شد." : e.message);
      btn.disabled = false; btn.textContent = "🔇 ضبط نمونه نویز (۳ثانیه)";
    }
  };

  function render(r, x, fs, rCur, nzMsg){
    $("an-res").style.display = "block";
    const box = $("v-box");
    if (nzMsg) box.insertAdjacentHTML("afterbegin", `<div class="hint" style="margin-bottom:6px;color:#c4b5fd">${nzMsg} — سیگنال قبل از آنالیز پاکسازی شد.</div>`);
    // فیوژن سطح: بدترین رأی دو کانال (r==null یعنی فقط کانال جریان)
    const lv = (rCur && (!r || LV_ORDER.indexOf(rCur.worst) > LV_ORDER.indexOf(r.level))) ? rCur.worst : r.level;
    const chanTag = (r && rCur) ? " · فیوژن ۲ کاناله" : (!r ? " · فقط کانال جریان" : "");
    if (lv === "ok"){ box.className = "verdict ok";
      box.innerHTML = `✅ <span><b>سالم${chanTag}</b> — امضای عیبی دیده نشد${rCur ? ` (BRB: ${rCur.brbDb.toFixed(1)} dB)` : ""}</span>`;
    } else {
      const lvlFa = lv === "alarm" ? "🔴 بحرانی" : lv === "warning" ? "🟡 هشدار جدی" : "🟠 تحت پایش";
      const parts = [];
      if (r && r.level !== "ok") parts.push(`بلبرینگ: <b>${r.faName} [${r.code}]</b> (${r.best}=${FA(r.bestVal*100)}٪)`);
      if (rCur && rCur.findings.length)
        parts.push(...rCur.findings.map(f => `جریان: <b>${f.fa} [${f.code}]</b>`));
      box.className = "verdict " + (lv === "ok" ? "ok" : lv === "warning" ? "watch" : lv);
      box.innerHTML = `⚠️ <span>${lvlFa}${chanTag} — ${parts.join(" · ") || "بدون یافته جدی"}</span>`;
    }
    // کارت کانال جریان
    if (rCur){
      const cf = $("cur-card");
      cf.style.display = "block";
      cf.innerHTML = `<h3 style="font-size:15px;margin-bottom:8px">⚡ کانال جریان (MCSA)</h3>` +
        `<div class="metrics" style="grid-template-columns:repeat(4,1fr)">` +
        [["f₁ شبکه", FA(rCur.f1)+"Hz"], ["سایدبند BRB", rCur.brbDb.toFixed(1)+"dB"],
         ["THD", FA(rCur.thd)+"٪"], ["SNR سایدبند", FA(rCur.sbSnr)+"×"]]
        .map(([l,v]) => `<div class="metric"><div class="v">${v}</div><div class="l">${l}</div></div>`).join("") +
        `</div>` + (rCur.findings.length
          ? rCur.findings.map(f => `<div style="font-size:13.5px;color:var(--mut)">• <b style="color:var(--warn)">${f.fa}</b> — ${f.detail}</div>`).join("")
          : `<div style="font-size:13.5px;color:var(--ok)">• امضای میله‌شکسته/هارمونیک دیده نشد (BRB ≤ −${-(-54)}dB)</div>`);
    } else $("cur-card").style.display = "none";
    if (r){
      const mets = [
        ["کرتوز", FA(r.kurt)], ["RMS", r.rms.toPrecision(3)], ["ضریب اوج", FA(r.crest)],
        ["BPFO", FA(r.res.bpfo*100)+"٪"], ["BPFI", FA(r.res.bpfi*100)+"٪"], ["BSF", FA(r.res.bsf*100)+"٪"],
      ];
      if (r.ac) mets.push(["مرکز طیف صوت", FA(r.ac.centroid)+"Hz"], ["باند ۱–۴kHz", FA(r.ac.b3*100)+"٪"]);
      $("v-metrics").innerHTML = mets.map(([l,v]) =>
        `<div class="metric"><div class="v">${v}</div><div class="l">${l}</div></div>`).join("");
      $("cv").style.display = $("cv2").style.display = "block";
      plotWave($("cv"), x);
      plotEnv($("cv2"), r, fs);
    } else {
      $("v-metrics").innerHTML = "";
      $("cv").style.display = $("cv2").style.display = "none";
    }
  }
  function setupCanvas(c){
    const dpr = window.devicePixelRatio || 1, W = c.clientWidth, H = parseInt(c.getAttribute("height"));
    c.width = W * dpr; c.height = H * dpr;
    const ctx = c.getContext("2d"); ctx.scale(dpr, dpr);
    return [ctx, W, H];
  }
  function plotWave(c, x){
    const [ctx, W, H] = setupCanvas(c), n = Math.min(8192, x.length);
    ctx.fillStyle = "#9db0d4"; ctx.font = "12px Vazirmatn"; ctx.fillText("سیگنال خام — " + FA(n/fsFromInput()) + " ثانیه اول", 12, 18);
    ctx.strokeStyle = "#38bdf8"; ctx.lineWidth = 1; ctx.beginPath();
    const mid = H * 0.62, amp = H * 0.3;
    let mx = 1e-12; for (let i = 0; i < n; i++) mx = Math.max(mx, Math.abs(x[i]));
    for (let px = 0; px < W; px++){
      const i0 = Math.floor(px * n / W), i1 = Math.max(i0 + 1, Math.floor((px + 1) * n / W));
      let lo = 1e9, hi = -1e9;
      for (let i = i0; i < i1; i++){ const v = x[i]; if (v < lo) lo = v; if (v > hi) hi = v; }
      ctx.moveTo(px, mid - (hi / mx) * amp); ctx.lineTo(px, mid - (lo / mx) * amp + 1);
    }
    ctx.stroke();
  }
  function fsFromInput(){ return parseFloat($("fs").value) || 1; }
  function plotEnv(c, r, fs){
    const [ctx, W, H] = setupCanvas(c);
    const fe = r.fe, Ae = r.Ae, fMax = Math.min(500, fs / 2);
    let yMax = 1e-12;
    for (let i = 0; i < fe.length && fe[i] <= fMax; i++) yMax = Math.max(yMax, Ae[i]);
    const padL = 46, padB = 30, padT = 34, w = W - padL - 14, h = H - padT - padB;
    const X = f => padL + w * f / fMax, Y = v => padT + h * (1 - v / yMax);
    ctx.fillStyle = "#9db0d4"; ctx.font = "12px Vazirmatn";
    ctx.fillText("طیف پوش با نشانگرهای فرکانس عیب", 12, 18);
    ctx.strokeStyle = "#22315a"; ctx.lineWidth = 1; ctx.beginPath();
    for (let gx = 0; gx <= fMax; gx += 100){
      ctx.moveTo(X(gx), padT); ctx.lineTo(X(gx), padT + h);
      ctx.fillText(String(gx), X(gx) - 8, padT + h + 16);
    }
    ctx.stroke();
    // نشانگرها
    const marks = [["BPFO", "#fb7185"], ["BPFI", "#f5a524"], ["BSF", "#a78bfa"]];
    ctx.setLineDash([4, 4]);
    for (const [nm, col] of marks){
      for (let hh = 1; hh <= 3; hh++){
        const f = hh * r.frqs[nm]; if (f > fMax) break;
        ctx.strokeStyle = col; ctx.lineWidth = hh === 1 ? 1.6 : 1;
        ctx.beginPath(); ctx.moveTo(X(f), padT); ctx.lineTo(X(f), padT + h); ctx.stroke();
      }
      ctx.fillStyle = col; ctx.fillText(nm, X(r.frqs[nm]) - 14, padT - 6);
    }
    ctx.setLineDash([]);
    ctx.strokeStyle = "#38bdf8"; ctx.lineWidth = 1.3; ctx.beginPath();
    let started = false;
    for (let i = 0; i < fe.length && fe[i] <= fMax; i++){
      if (fe[i] < 5) continue;
      const px = X(fe[i]), py = Y(Ae[i]);
      if (!started){ ctx.moveTo(px, py); started = true; } else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }
})();

// ══════ PWA — ثبت سرویس‌ورکر (آفلاین کامل) ══════
if ("serviceWorker" in navigator) {
  window.addEventListener("load", () =>
    navigator.serviceWorker.register("?mmds=sw").catch(() => {}));
}
</script>
</body>
</html>
